(async () => {
  const J = {'Content-Type': 'application/json', 'X-Gigg-CSRF': '1'};
  const mk = (b) => fetch('/api/v1/projects/1/gigs', {method: 'POST', headers: J, body: JSON.stringify(b)}).then(r => r.json());
  for (let i = 1; i <= 9; i++) await mk({title: 'Lane card ' + i, category: 'todo'});
  const rb = await mk({title: 'QA runbook check', category: 'waiting'});
  const dt = await mk({title: 'Date field check', category: 'doing', checklist: ['Check the date']});
  localStorage.setItem('qaRb', rb.key); localStorage.setItem('qaDt', dt.key); localStorage.setItem('qaDtId', String(dt.id));
  const f = await fetch('/api/v1/workspaces/scout/fields', {method: 'POST', headers: J, body: JSON.stringify({name: 'Reviewed', kind: 'checkbox'})});
  const e = await fetch('/api/v1/workspaces/scout/errands', {method: 'POST', headers: J, body: JSON.stringify({name: 'QA disk check', command: 'true', worker: 'scout', rule: {freq: 'daily', interval: 1, window_start: '03:00', window_minutes: 60, lead_minutes: 0, tz: 'UTC'}})});
  const ej = await e.json(); localStorage.setItem('qaErrand', String(ej.id));
  const u = await fetch('/api/v1/users', {method: 'POST', headers: J, body: JSON.stringify({username: 'carol', kind: 'human', display_name: 'Carol'})});
  return [!!rb.key, !!dt.key, f.status, e.status, u.status];
})()
